// Audio data. Which sound plays for which game event lives here, NOT in puzzle code: puzzles only
// announce events; this table decides what they sound like.
// Files are generated by tools/generate-sounds.py into public/sounds/.

// category: 'ui' and 'sfx' follow the Effects slider, 'ambient' follows the Ambient slider.
// volume: per-sound trim (0..1) so loud/quiet files sit together. minIntervalMs: anti-spam gate.
export const SOUNDS = Object.freeze({
  ui_click: { file: 'ui_click.wav', category: 'ui', volume: 0.9, minIntervalMs: 40 },
  dialogue: { file: 'dialogue.wav', category: 'ui', volume: 0.6, minIntervalMs: 150 },
  button: { file: 'button.wav', category: 'sfx', volume: 1, minIntervalMs: 120 },
  locked: { file: 'locked.wav', category: 'sfx', volume: 1, minIntervalMs: 400 },
  door_slide: { file: 'door_slide.wav', category: 'sfx', volume: 0.9, minIntervalMs: 350 },
  door_open: { file: 'door_open.wav', category: 'sfx', volume: 1, minIntervalMs: 500 },
  success: { file: 'success.wav', category: 'sfx', volume: 0.9, minIntervalMs: 500 },
  level_complete: { file: 'level_complete.wav', category: 'sfx', volume: 0.9, minIntervalMs: 1000 },
  teleport: { file: 'teleport.wav', category: 'sfx', volume: 0.9, minIntervalMs: 400 },
  glitch: { file: 'glitch.wav', category: 'sfx', volume: 0.8, minIntervalMs: 300 },
  transition: { file: 'transition.wav', category: 'sfx', volume: 0.8, minIntervalMs: 300 },
  stage_up: { file: 'stage_up.wav', category: 'sfx', volume: 0.9, minIntervalMs: 1000 },
  ending: { file: 'ending.wav', category: 'sfx', volume: 0.9, minIntervalMs: 1000 },
  secret: { file: 'secret.wav', category: 'sfx', volume: 0.9, minIntervalMs: 1000 },
  presence: { file: 'presence.wav', category: 'sfx', volume: 0.9, minIntervalMs: 1500 },
  ambient_room: { file: 'ambient_room.wav', category: 'ambient', volume: 1, loop: true },
  ambient_corrupt: { file: 'ambient_corrupt.wav', category: 'ambient', volume: 1, loop: true },
})

// Game event name (the same names dialogue and corruption use) -> sound id(s).
export const EVENT_SOUNDS = Object.freeze({
  door_rejected: 'door_slide', // the troll door dodged
  button_pressed: 'button',
  button_a: 'button',
  button_b: 'button',
  calibrated: 'button',
  door_locked: 'locked',
  fake_exit: 'teleport',
  door_fake: 'teleport', // Level 8's fake doors
  sequence_step: 'button',
  sequence_wrong: 'locked',
  sequence_solved: 'success',
  blackout_start: 'stage_up', // the lights going out
  lights_wrong: 'locked',
  lights_unlocked: 'success',
  gate_open: 'door_slide', // Level 7's gate announces itself, so the blind trick has a sound cue
  gate_close: 'door_slide',
  presence_appears: 'presence',
  ambient_glitch: 'glitch', // unexpected events at higher corruption
  ambient_presence: 'presence',
  controls_reversed: 'glitch',
  sign_changed: 'glitch',
  level_complete: 'door_open',
  corruption_stage_1: 'stage_up',
  corruption_stage_2: 'stage_up',
  corruption_stage_3: 'stage_up',
})

// Ambient: the room loop always plays; the corrupt drone fades in with the corruption stage.
export const AMBIENT_ROOM = 'ambient_room'
export const AMBIENT_CORRUPT = 'ambient_corrupt'
export const CORRUPT_LAYER_BY_STAGE = Object.freeze([0, 0.25, 0.6, 1])
export const AMBIENT_DUCK = 0.35 // ambient level while paused
export const AMBIENT_FADE_MS = 800
export const AMBIENT_STAGE_FADE_MS = 1500

export const AUDIO_BASE_URL = `${import.meta.env?.BASE_URL ?? '/'}sounds/`
